# Transcript of the cut YO video in CapCut (14:49). (section start "m:ss", text)
END = "14:49"
SECTIONS = [
("0:00", """Ако искаш да започнеш онлайн бизнес, но нямаш идея какво точно да продаваш, в това видео ще ти покажа няколко вида дигитални продукти, които можеш да създадеш и продаваш изцяло онлайн. Ще видиш как работи всеки от тях, какъв проблем може да решава, и ще ти дам конкретни примери, за да можеш още докато гледаш видеото да прецениш кой вариант би бил най-подходящ за теб. Причината да ти показвам точно този модел е, че вече съм изграждал и продавал дигитални продукти на практика. Един от продуктите ми генерира над 49 000 евро за около 6 месеца, а друг продукт е генерирал над 1,2 милиона евро за по-малко от 2 години. И преди да преминем към продукт номер 1, абонирай се за канала, за да не изпускаш още подобни видеа."""),
("0:41", """Номер едно. Наръчник. Това е буквално един от най-лесните, с които можеш да започнеш, или така наречените практически наръчници. Това може да бъде PDF, който води човека стъпка по стъпка до конкретен резултат. Като например, вместо да направиш книга на тема „здравословно хранене“, можеш да направиш „30 лесни вечери за хора, които искат да отслабнат, но нямат време да готвят“. Например, разликата е огромна, защото реално вторият продукт решава много по-конкретен проблем. Не е необходимо наръчникът да бъде много дълъг и точно това му е предимството, защото ако можеш да решиш проблема на конкретния човек, а именно че не знае какво да си изготви, да речем, по-добре да си реши проблема по-бързо и по-лесно в 30 страници, отколкото да чете книга от 200. Хората не плащат за броя страници, а плащат за това да им се реши проблемът. И дори колкото по-бързо и лесно им се реши проблемът, толкова по-добре. Защото, замисли се, когато те боли зъб, искаш на момента да спре да те боли, а не да спре да те боли след 5 часа, например. На абсолютно същия принцип работи и това. Като AI всъщност може значително да ускори проучването, структурата и първата версия на съдържанието. Но в крайна сметка информацията трябва да бъде проверена и продуктът трябва реално да бъде полезен, а не да взимаме пари за нещо, което не дава наистина практическа стойност. Самият формат е прост, евтин е за създаване и може да бъде доставен автоматично след покупката."""),
("2:06", """Следващото нещо е шаблони. Това са вторият тип продукти, които ще разгледаме днес. Като тук човек не плаща толкова за самата информация, колкото за това просто да не започва от празен лист. Представи си, да речем, собственик на малък бизнес, който трябва да направи месечен план за съдържание, трябва да публикува съдържание в социалните мрежи. Вместо всеки ден да се чуди какво да публикува, буквално можеш да му продадеш готов календар с идеи, структури и примери. Също може да работи за всякакви сфери, като CV-та например – готов шаблон за CV, или бюджети – някакви готови шаблони за това как да си разпределяш бюджета, презентации – да речем, някой трябва да излезе на сцената и да води презентация, може да му подготвим слайдовете, той само да си замени думите, или пък бизнес планове, договори, всякакви такива неща. Като голямото предимство е, че резултатът в случая се вижда веднага, защото човекът буквално получава точно това, което иска, на секундата и много лесно може да го адаптира спрямо неговите цели, неговите нужди. Буквално отваря файла и може директно да започне да го използва. Това прави стойността на продукта много по-лесна за обяснение. Като отново, разбира се, AI може да помогне и в този конкретен случай."""),
("3:18", """Номер 3 е планер. Планерите работят добре, когато проблемът на човека е по-скоро свързан с организация и последователност. Това може да бъде, да речем, финансов планер, хранителен планер, фитнес тракер, сватбен планер или пък някаква система за управление на малък бизнес. Сега ще дам пример. Представи си човек, който, да речем, всеки месец се пита къде са му изчезнали парите. Вместо да му дадеш 50 страници теория за финансите, можеш да му дадеш проста система, в която буквално си записва приходи, разходи, спестявания и цели, и така продуктът се превръща в инструмент, който може много по-бързо да използва и да го използва дългосрочно, а не просто да прочете нещо и да го забрави след 2 дни. Реално това може да бъде под формата на PDF, Excel, Google Sheets или… няма, честно казано, толкова голямо значение. Като тук също нещо е много важно и то всъщност важи за всичките дигитални продукти, и то е, че колкото по-конкретна е аудиторията, толкова по-ясно можеш да решиш нейния проблем. Едно е, да кажем, „планер за лични финанси“. Това е много общо, много широко и не толкова хора биха се разпознали в него. Докато, ако кажем „бюджетна система за семейство с две деца“, вече е много по-конкретна оферта. Няма нужда да казвам, отново AI може да помогне всъщност с това."""),
("4:32", """И между другото, преди да продължим, в описанието на видеото съм оставил линк към напълно безплатно обучение, в което показвам цялата система стъпка по стъпка: как намираме печеливша ниша, в която да позиционираме дигиталния си продукт, тоест да видим различни проблеми, които хората вече имат и са готови да плащат за тях; след това как да създадем страница, да създадем офертата си около тази печеливша ниша, да тестваме възможно най-бързо с по-малко от 50 евро бюджет, да видим дали хората имат интерес към нашия дигитален продукт, и тогава вече да го създадем, да го развием и да го превърнем в бизнес, който ни генерира между 2500 и над 5000 евро на месец печалба. Можеш да го вземеш напълно безплатно, като просто цъкнеш на линка под това видео."""),
("5:17", """Нека се върнем и към четвъртия, именно чеклист. Чеклистът изглежда като много прост продукт, но понякога точно това е неговото предимство. Той буквално може да бъде една страница, даже може и по-малко от една страница. Защото хората често не искат още един огромен курс, искат да знаят дали са направили всичко необходимо. Например, родители могат да купят чеклист за подготовка на дете за първи клас. Човек, който се мести в друга държава, може да има нужда от списък с документи и задачи, които трябва да изпълни, за да е сигурен, че не изпуска нищо. Булка може да иска сватбен чеклист за, примерно, последните три месеца преди събитието, за да е всичко организирано. Нали знаеш, има едно такова усещане, че все нещо забравяш. И такъв тип продукти всъщност са много полезни точно в тези ситуации. Като стойността от самия продукт идва от това, че премахва притеснението именно на това нещо: „Не забравям ли нещо?“ – този вътрешен глас, който постоянно се върти в главата ни. Като един такъв продукт може да бъде сравнително кратък, както вече казах, но много, много, много полезен. А между другото, даже можеш да го комбинираш с някакви инструкции, таблици или пък готови ресурси и така всъщност да увеличиш още повече стойността. Като това е много добър пример за това защо един продукт не е задължително да бъде сложен, за да бъде продаваем и да носи стойност. Просто трябва да решава реален проблем."""),
("6:39", """Следващото, или номер 5, е видео обучение. Ако даден резултат изисква повече обяснение, повече демонстрация, доста често видеото е по-подходящо от някакъв текстов формат или пък дори аудио формат. Например, можеш да направиш обучение как се работи с конкретен софтуер, как се настройва рекламна кампания, как се използва даден AI инструмент, или как да си ремонтираш нещо вкъщи, или как да си смениш гумата на колата. Сега, ако искам да сменя гумата на колата, най-добре ще е да го видя на видео, а не да го слушам или да го чета. Така че в доста ситуации всъщност видеата са доста по-полезни, отколкото хартиените или аудио носителите. Като едно от големите предимства тук е всъщност, че ние записваме видеата веднъж – всъщност като и на другите дигитални продукти, – но тук може просто записването на видеата да отнеме една идея повече време. Но просто ги предоставяме на всеки един клиент отново и отново, той ги гледа и получава стойност, без да разменяме времето си за пари. То всъщност около това се върти цялостният бизнес модел с дигитални продукти – именно че се създават веднъж и не се налага отново и отново да обслужваме клиентите, ами те си купуват дигиталните продукти, които сме създали, и ние получаваме месечни приходи от продажби, а сме създали продукта веднъж. Много хора обаче, когато говорим за видео обученията, правят грешката първо да записват 30 часа видео и чак след това да видят дали някой би купил това обучение. Като по-добрият подход е първо да видиш дали има интерес към резултата, който обещаваш, и ако пазарът покаже интерес, тогава чак да инвестираш времето в създаването му."""),
("8:19", """Номер 6. Ресурсен пакет. Ресурсният пакет комбинира няколко малки инструмента в един продукт. Например, вместо да продаваш само един шаблон, можеш да обединиш много шаблони и да ги продаваш като комплект. Много добре работи, между другото, това са готови команди към ChatGPT – просто го давам като пример – да речем 50 команди за ChatGPT, които да ти помогнат да пишеш по-добри имейли за твоите клиенти. Този тип продукт работи особено добре при бизнес аудитории, защото спестява много време. А както най-вероятно знаеш, всъщност това е едно от нещата, с които бизнесите най-често страдат – просто имат много, много проблеми и много отговорности и търсят нещо, което да им спести време. Така че това е просто допълнителен съвет, ако ще продаваш на бизнеси."""),
("9:06", """Седмият и последен е AI Prompt Pack. Като AI Prompt пакетите са сравнително нов тип дигитален продукт. Самият продукт представлява буквално готови инструкции, които помагат на човек да използва AI по-ефективно за конкретна задача. Например, можеш да направиш „100 ChatGPT команди за брокери на имоти“. Вътре може да има промптове за това как да си описват обявите по-добре, как да си менажират социалните мрежи по-добре, как ChatGPT да пише имейлите към клиентите им по-добре и т.н. Тоест буквално те да вземат тези команди, да ги използват в ChatGPT или някои от другите AI-подобни лангвидж модели, и AI да свърши работата по-добре за тях. Причината човек да плати за нещо подобно или да има интерес към нещо подобно е, че не иска сам да открива какво да пита AI и как да структурира всяка заявка. Но тук има една много важна подробност. Не продаваш просто списък с въпроси към ChatGPT, а трябва да продаваш по-бърз и по-добър начин продуктът да върши конкретната работа. Или с други думи, даже тук ще изляза от контекста просто на този дигитален продукт, ами ще говоря генерално за всички дигитални продукти. Ние никога не продаваме самия продукт. Ние продаваме решението на проблема, който този дигитален продукт носи. Това е изключително важен бизнес съвет. Никой не иска да ходи на фитнес всеки ден и да спазва диета, но искат да изглеждат добре. Следователно ние не продаваме процеса, ние продаваме крайния резултат. Същото е и тук – ние не продаваме просто „готово, ето ти, купи ChatGPT шаблони“. Не, ние продаваме резултата, който хората биха имали, ако си купят тези ChatGPT шаблони или команди и така нататък. И тук говоря за абсолютно всеки един дигитален продукт, ако създаваш бизнес около него."""),
("10:53", """И номер 8. Готова система. Последният вариант е да комбинираш няколко от предишните продукти в цялостна система. Това обикновено позволява и по-висока цена, защото не даваш само един инструмент, а решение от начало до край. И честно казано, това е абсолютно любимият ми дигитален продукт и съм го оставил за накрая само за най-сериозните, които са изгледали видеото. И това е дигиталният тип продукт, който е изкарал на мен и на моите ученици най-много пари. Вместо да ти продавам просто списък с 30 вечери, които можеш да си приготвиш вкъщи, и готов чеклист за това дали си спазваш диетата, например, мога да ти продам цялостна трансформация. Даже не информация, а трансформация – за това да преминеш от човек с наднормено тегло до това всъщност да влезеш в най-добрата си форма в рамките на 12 седмици. И това може да включва рецепти за готвене, може да включва персонална помощ, може да включва обучителни материали, може да включва групови срещи, може да включва чат комуникация. Тоест цялостен дигитален продукт, който съдържа много компоненти и решава цялостния проблем. Така можем да взимаме много повече пари за дигиталния продукт – буквално 200, 300, 500 евро и нагоре. Като най-често учениците ми продават такива цялостни дигитални продукти в диапазона между 1900 евро до 8800 евро. Следователно ние можем с една продажба, една на месец, да изкараме наистина много, много, много добри пари. И тук всъщност и тези продукти са възприемани като много по-стойностни поради проста причина, че ако влезем в магазин и видим два вида салам – единият е 5 евро, другият е 50 евро – естествено, че ще си помислим, че този за 50 е по-качествен. Затова всъщност ние, продавайки цялостен дигитален продукт, който решава цялостния проблем под формата на трансформация – като цялостно обучение или цялостна коучинг програма, или цялостна менторска програма – ние всъщност караме хората да си мислят, че това наистина е нещо качествено и нещо, което наистина може да им реши проблема. Защото ако аз сега ви кажа, че ще ви помогна да стартирате онлайн бизнес за 50 евро и че ще ви помагам, ще съм до вас нон-стоп и така нататък, ще си помислите: „Абе, тук нещо не е наред, тук има явно някакъв скам.“ Твърде хубаво, за да е истина. Точно затова всъщност това е любимият ми дигитален продукт. Това, което може би сега ти изниква в съзнанието, е: „Добре де, ама аз ако не съм експерт в тази конкретна сфера, как може да взимам 23 500 до 8800 евро за такъв тип продукт?“ И тук идва следващото нещо, което всичките ми ученици – или айде, не всички, но голяма част от тях – правят: че си партнират с експерт, който вече е добър в това конкретно нещо. Вместо те да стават фитнес треньори, просто си партнират с фитнес треньор, разделят си печалбата 50 на 50, например. Фитнес треньорът застава пред камерата, говори, дава стойност, а пък моите ученици в случая седят пред компютъра, те създават дигиталния продукт, те създават маркетинга, правят така, че хората да разберат за този продукт, да го купуват, и прибират 50% от печалбата най-често, или между 30% и 50% от цялата печалба, без абсолютно никой да знае за тях, без те да имат никаква отговорност към клиентите и буквално докато седят само единствено на компютъра. И заради това обожавам този бизнес модел, именно с дигиталните продукти, и заради това всъщност това е най-добрият бизнес модел в момента през 2026 година. Разбира се, не само заради това, и заради още няколко причини, но нека да не разводняваме видеото."""),
("14:27", """Всъщност даже ще сложа точката тук. Това бяха част от дигиталните продукти, които можеш да създадеш буквално още от утре. Така че ако това видео ти е било полезно, абонирай се за канала. Напълно безплатно е, ще ти отнеме една секунда, но всъщност нямаш абсолютно никаква представа колко много това нещо помага на всичко, което правя. Така че благодаря ти и те очаквам в следващото видео."""),
]
